mapper.select:
SELECT queue_id, created_ts, done_ts, done, status_id, result_id, type_id, reference, original_reference, account_id, psp_event_queue_id, idempotency_key, merchant_reference, success, amount, currency_id, psp_reference, NULL::BIGINT AS transaction_id FROM accounting_request_queue WHERE (type_id = #{typeId} AND reference = #{reference}) OR (account_id = #{accountId} AND idempotency_key = #{idempotencyKey})
OR psp_event_queue_id = #{pspEventQueueId}
ORDER BY queue_id LIMIT 1
